struct ScopedImage{OfxPropertySetHandle handle=nullptr;~ScopedImage(){if(handle)fx->clipReleaseImage(handle);}};static ConstImageView readImage(OfxPropertySetHandle h){void*p=nullptr;int bounds[4],rowBytes=0;char*depth=nullptr,*components=nullptr;check(prop->propGetPointer(h,kOfxImagePropData,0,&p));check(prop->propGetIntN(h,kOfxImagePropBounds,4,bounds));check(prop->propGetInt(h,kOfxImagePropRowBytes,0,&rowBytes));check(prop->propGetString(h,kOfxImageEffectPropPixelDepth,0,&depth));check(prop->propGetString(h,kOfxImageEffectPropComponents,0,&components));if(!p||std::strcmp(depth,kOfxBitDepthFloat)||std::strcmp(components,kOfxImageComponentRGBA))throw kOfxStatErrFormat;return{static_cast<float*>(p),bounds[2]-bounds[0],bounds[3]-bounds[1],4,rowBytes};}
