static void copy(const ConstImageView&s,ImageView d){for(int y=0;y<d.height;++y){auto*dst=reinterpret_cast<float*>(reinterpret_cast<unsigned char*>(d.data)+std::ptrdiff_t(y)*d.row_bytes);auto*src=reinterpret_cast<const float*>(reinterpret_cast<const unsigned char*>(s.data)+std::ptrdiff_t(y)*s.row_bytes);std::copy(src,src+d.width*4,dst);}}
